def take(n, iterable):
    result = []
    for i, x in enumerate(iterable):
        if i >= n:
            break
        result.append(x)
    return result

def drop(n, iterable):
    result = []
    for i, x in enumerate(iterable):
        if i >= n:
            result.append(x)
    return result

def unique_by(lst, key_func):
    seen = set()
    result = []
    for item in lst:
        key = key_func(item)
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result
